    // 1. Null pointer check
    if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Validate finiteness of all inputs
    if ((!isfinite(wheel->axis_body.x)) || (!isfinite(wheel->axis_body.y)) || (!isfinite(wheel->axis_body.z)) ||
        (!isfinite(wheel->inertia_kg_m2)) || (!isfinite(wheel->speed_rad_s)) ||
        (!isfinite(motor_torque)) || (!isfinite(dt)) || (!isfinite(speed_limit))) {
        return ADCS_E_RANGE;
    }

    // 3. Validate physical constraints: inertia > 0, dt >= 0, speed_limit > 0
    if (wheel->inertia_kg_m2 <= 0.0 || dt < 0.0 || speed_limit <= 0.0) {
        return ADCS_E_RANGE;
    }

    // 4. Validate axis norm > 1e-12
    double axis_norm = adcs_vec3_norm(&wheel->axis_body);
    if (axis_norm <= 1e-12) {
        return ADCS_E_RANGE;
    }

    // 5. Normalize the wheel axis: a = normalize(axis)
    adcs_vec3_t a = adcs_vec3_scale(&wheel->axis_body, 1.0 / axis_norm);

    // 6. Compute unclamped speed: omega_unclamped = omega + motor_torque * dt / J
    double omega_unclamped = wheel->speed_rad_s + (motor_torque * dt) / wheel->inertia_kg_m2;

    // 7. Determine saturation status: *saturated is 1 if |omega_unclamped| > speed_limit, else 0
    if (fabs(omega_unclamped) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    // 8. Clamp speed magnitude: omega_next = clamp(omega_unclamped, -speed_limit, +speed_limit)
    double omega_next = omega_unclamped;
    if (omega_next > speed_limit) {
        omega_next = speed_limit;
    } else if (omega_next < -speed_limit) {
        omega_next = -speed_limit;
    }

    // 9. Update next_wheel record: axis=a, inertia=J, speed=omega_next
    next_wheel->axis_body = a;
    next_wheel->inertia_kg_m2 = wheel->inertia_kg_m2;
    next_wheel->speed_rad_s = omega_next;

    // 10. Map scalar angular momentum onto body axis: h_next = J * omega_next * a
    double h_scalar = wheel->inertia_kg_m2 * omega_next;
    next_momentum->x = h_scalar * a.x;
    next_momentum->y = h_scalar * a.y;
    next_momentum->z = h_scalar * a.z;

    return ADCS_OK;
}

